export const riverNow=Date.parse('2026-10-28T20:00:00Z'),riverAt=h=>new Date(riverNow+h*3600000).toISOString();
export function riverProduct({level=3,observed=3,issue=-1}={}){return {revision:'r'+level+'-'+observed+'-'+issue,checked_at:riverAt(0),metadata:{lid:'TEST1',name:'Test River',latitude:39,longitude:-77,datums:{vertical:{value:[{abbrev:'NAVD88',value:100}]}},flood:{stageUnits:'ft',categories:{action:{stage:4},minor:{stage:7},moderate:{stage:10},major:{stage:14}}}},series:{observed:{primaryName:'Stage',primaryUnits:'ft',data:[{validTime:riverAt(-1),primary:observed}]},forecast:{primaryName:'Stage',primaryUnits:'ft',issuedTime:riverAt(issue),data:Array.from({length:14},(_,i)=>({validTime:riverAt(i*6),primary:level}))}}};}
